使用示例： autosession=make_shared<websocket_session>(move(sock));
session->set_message_handler([](conststring&msg,websocket_opcodeopcode){
if(opcode==websocket_opcode::TEXT){
println("Text:",msg);
}else{
//处理二进制消息
}
});
session->set_close_handler([](websocket_statusstatus,conststring&reason){
println("Closed:",static_cast<int>(status),"-",reason);
});
session->start();
